// Publish settings
// Target repository and branches. The PR branch is reset to main on every
// run and gets the full generated files, so one open pull request always
// shows the complete difference between the database and main.
// Mode: Run Once for All Items.

const repo = 'lukaszFD/sentinel-blocklists';
return [{
  json: {
    repo,
    owner: repo.split('/')[0],
    api: `https://api.github.com/repos/${repo}`,
    base: 'main',
    branch: 'n8n/daily-update',
    lists: ['malicious', 'tracking', 'telemetry'],
  },
}];

// Plan list files
// One item per list file: the generated content and its path in the repo.
// Mode: Run Once for All Items.

const s = $('Publish settings').first().json;
const files = $('Render lists').first().json.files || {};
return s.lists.map((list) => ({
  json: { list, path: `lists/${list}.txt`, rendered: String(files[list] ?? '') },
}));

// Compare lists
// Generated files vs the files on main. action:
//   error      token missing, GitHub unreachable, main unreadable
//   no_change  every file equal to main
//   changed    at least one file differs (added / removed per list)
// Mode: Run Once for All Items.

const s = $('Publish settings').first().json;
const render = $('Render lists').first().json;
const vault = $('GitHub token').first().json;
const main = $('Get main branch').first().json;
const plan = $('Plan list files').all().map((i) => i.json);
const got = $input.all().map((i) => i.json);

const entries = (text) => String(text || '').split('\n').map((l) => l.trim()).filter((l) => l && !l.startsWith('#'));
const errText = (res) => String(res?.error?.message || res?.error || res?.body?.message || '').slice(0, 300);

let action = 'changed';
let message = null;
const changed = [];
const counts = {};
let added = 0;
let removed = 0;

if (vault.error || !vault.data?.token) {
  action = 'error';
  message = 'Vault secret cyber-sentinel/api-keys/github/blocklists missing or unreadable - add vault_github_blocklists_token and run playbook 06.1.';
} else if (main.error || main.statusCode !== 200 || !main.body?.commit?.sha) {
  action = 'error';
  message = main.statusCode === 401
    ? 'GitHub rejected the token (HTTP 401) - expired or revoked? Create a new fine-grained PAT and re-run 06.1.'
    : `Cannot read ${s.repo} ${s.base}: HTTP ${main.statusCode ?? '?'} ${errText(main)}`;
} else {
  for (let i = 0; i < plan.length; i++) {
    const f = plan[i];
    const res = got[i] || {};
    let current = '';
    if (res.statusCode === 200) {
      current = typeof res.body === 'string' ? res.body : JSON.stringify(res.body ?? '');
    } else if (res.statusCode !== 404) {
      action = 'error';
      message = `Cannot read ${f.path}: HTTP ${res.statusCode ?? '?'} ${errText(res)}`;
      break;
    }
    const now = new Set(entries(f.rendered));
    const before = new Set(entries(current));
    const add = [...now].filter((d) => !before.has(d));
    const rem = [...before].filter((d) => !now.has(d));
    counts[f.list] = now.size;
    added += add.length;
    removed += rem.length;
    if (current !== f.rendered) changed.push({ list: f.list, path: f.path, content: f.rendered, added: add, removed: rem });
  }
  if (action !== 'error' && changed.length === 0) action = 'no_change';
}

const today = new Date().toISOString().slice(0, 10);
const listLines = changed.map((c) => {
  const fmt = (arr, sign) => arr.slice(0, 50).map((d) => `  ${sign} ${d}`).join('\n') + (arr.length > 50 ? `\n  ... ${arr.length - 50} more` : '');
  return `### ${c.list}.txt: +${c.added.length} -${c.removed.length}\n` +
    (c.added.length ? '```\n' + fmt(c.added, '+') + '\n```\n' : '') +
    (c.removed.length ? '```\n' + fmt(c.removed, '-') + '\n```\n' : '');
}).join('\n');

return [{
  json: {
    action,
    message,
    publish_enabled: Number(render.publish_enabled) === 1,
    pending_review: Number(render.pending_review) || 0,
    main_sha: main.body?.commit?.sha || null,
    main_tree: main.body?.commit?.commit?.tree?.sha || null,
    changed,
    counts,
    added,
    removed,
    commit_message: `Update lists: +${added} -${removed} (${today})`,
    pr_title: 'Daily blocklist update',
    pr_body: `Generated by Cyber Sentinel (n8n workflow "Blocklist Publish") on ${today}.\n\n` +
      `Full difference between the Cyber Sentinel database and \`main\`. The branch is rebuilt every day; ` +
      `merge when ready.\n\n${listLines}\n\nEntries now: ` +
      Object.entries(counts).map(([k, v]) => `${k} ${v}`).join(', ') + '.',
  },
}];

// Plan PR
//   write  lists differ from main: new commit on the PR branch, open or
//          update the pull request
//   close  lists equal main again (e.g. a candidate was rejected before
//          the merge) and a pull request is still open: close it
//   none   nothing to do
// Mode: Run Once for All Items.

const cmp = $('Compare lists').first().json;
const prs = $('Find open PR').first().json;
const ref = $('Get branch').first().json;
const pr = prs.statusCode === 200 && Array.isArray(prs.body) && prs.body.length ? prs.body[0] : null;

let mode = 'none';
if (cmp.action === 'changed') mode = 'write';
else if (cmp.action === 'no_change' && pr) mode = 'close';

return [{
  json: {
    mode,
    branch_exists: ref.statusCode === 200,
    pr_number: pr?.number ?? null,
    pr_url: pr?.html_url ?? null,
    lookup_error: prs.statusCode === 200 ? null : `Cannot list pull requests: HTTP ${prs.statusCode ?? '?'}`,
  },
}];

// Evaluate result
// One log row for every run, whichever path it took. Never throws.
// Mode: Run Once for All Items.

const cmp = $('Compare lists').first().json;
const ran = (name) => $(name).isExecuted;
const res = (name) => (ran(name) ? $(name).first().json : null);
const errText = (r) => String(r?.error?.message || r?.error || r?.body?.message || '').slice(0, 300);

let status;
let message = cmp.message;
let prNumber = null;
let prUrl = null;
const plan = res('Plan PR');

if (cmp.action === 'error') {
  status = 'error';
} else if (!cmp.publish_enabled) {
  status = 'dry_run';
  message = cmp.action === 'changed'
    ? `Publishing disabled (blocklist_publish_enabled = 0): +${cmp.added} -${cmp.removed} not sent.`
    : 'Publishing disabled (blocklist_publish_enabled = 0); lists equal main.';
} else if (plan?.lookup_error) {
  status = 'error';
  message = plan.lookup_error;
} else if (plan?.mode === 'write') {
  const steps = [['Create tree', 201], ['Create commit', 201], ['Point branch at commit', null], ['Open, update or close PR', null]];
  const failed = steps.find(([name, code]) => {
    const r = res(name);
    if (!r) return true;
    return code ? r.statusCode !== code : ![200, 201].includes(r.statusCode);
  });
  if (failed) {
    const r = res(failed[0]);
    status = 'error';
    message = r ? `${failed[0]}: HTTP ${r.statusCode ?? '?'} ${errText(r)}` : `${failed[0]} did not run (earlier step failed)`;
  } else {
    const pr = res('Open, update or close PR').body;
    status = 'published';
    prNumber = pr.number;
    prUrl = pr.html_url;
    message = `${plan.pr_number ? 'Updated' : 'Opened'} PR #${pr.number}: +${cmp.added} -${cmp.removed}.`;
  }
} else if (plan?.mode === 'close') {
  const r = res('Open, update or close PR');
  prNumber = plan.pr_number;
  prUrl = plan.pr_url;
  if (r && r.statusCode === 200) {
    status = 'no_change';
    message = `Lists equal main again; closed stale PR #${plan.pr_number}.`;
  } else {
    status = 'error';
    message = `Could not close stale PR #${plan.pr_number}: HTTP ${r?.statusCode ?? '?'} ${errText(r)}`;
  }
} else {
  status = 'no_change';
  message = 'Lists equal main.';
}

return [{
  json: {
    log: {
      status,
      counts: cmp.counts,
      added: cmp.action === 'error' ? null : cmp.added,
      removed: cmp.action === 'error' ? null : cmp.removed,
      pr_number: prNumber,
      pr_url: prUrl,
      message,
    },
    pending_review: cmp.pending_review,
    changed: cmp.changed.map((c) => ({ list: c.list, added: c.added, removed: c.removed })),
  },
}];

// Build e-mail
// Sent when a pull request was opened or updated (merge it on GitHub) and
// when the run failed. Domain names are HTML-escaped.
// Mode: Run Once for Each Item.

const esc = (value) => String(value ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const r = $('Evaluate result').first().json;
const log = r.log;
const ok = log.status === 'published';
const prLink = typeof log.pr_url === 'string' && log.pr_url.startsWith('https://github.com/')
  ? `<a style="color:#90caf9;" href="${esc(log.pr_url)}">PR #${esc(log.pr_number)}</a>` : '';
const lists = r.changed.map((c) =>
  `<p style="margin:10px 0 2px;"><strong>${esc(c.list)}.txt</strong>: +${c.added.length} -${c.removed.length}</p>` +
  (c.added.length ? `<div style="font-family:monospace;color:#81c784;">${c.added.slice(0, 30).map(esc).join('<br>')}${c.added.length > 30 ? '<br>…' : ''}</div>` : '') +
  (c.removed.length ? `<div style="font-family:monospace;color:#ff8a80;">${c.removed.slice(0, 30).map(esc).join('<br>')}${c.removed.length > 30 ? '<br>…' : ''}</div>` : '')
).join('');

return {
  json: {
    subject: ok
      ? `[Cyber Sentinel] Blocklists: PR #${log.pr_number} ready to merge (+${log.added} -${log.removed})`
      : '[Cyber Sentinel] Blocklists: publishing failed',
    html: `<div style="font-family:Arial,sans-serif;background:#1e1e1e;color:#e0e0e0;padding:20px;">
<h2 style="margin:0 0 12px;">${ok ? 'Own blocklists — pull request ready' : 'Own blocklists — publishing failed'}</h2>
<p>${esc(log.message)} ${prLink}</p>
${ok ? lists + '<p style="margin-top:14px;">Pi-hole picks the change up after the merge, on its next gravity update.</p>' : ''}
${r.pending_review ? `<p>${esc(r.pending_review)} candidate(s) still wait for review on the Blocklists page.</p>` : ''}
</div>`,
  },
};
